/// Content block in a response message.
///
/// Response content blocks represent different types of content
/// generated by the model. Unknown types are preserved as
/// [UnknownContentBlock] for forward compatibility.
sealed class ContentBlock {
  const ContentBlock();

  /// Creates a [ContentBlock] from JSON.
  factory ContentBlock.fromJson(Map<String, dynamic> json) {
    final type = json['type'] as String;
    return switch (type) {
      'text' => TextBlock.fromJson(json),
      'thinking' => ThinkingBlock.fromJson(json),
      'redacted_thinking' => RedactedThinkingBlock.fromJson(json),
      'tool_use' => ToolUseBlock.fromJson(json),
      'server_tool_use' => ServerToolUseBlock.fromJson(json),
      'web_search_tool_result' => WebSearchToolResultBlock.fromJson(json),
      'web_fetch_tool_result' => WebFetchToolResultBlock.fromJson(json),
      'code_execution_tool_result' => CodeExecutionToolResultBlock.fromJson(
        json,
      ),
      'bash_code_execution_tool_result' =>
        BashCodeExecutionToolResultBlock.fromJson(json),
      'text_editor_code_execution_tool_result' =>
        TextEditorCodeExecutionToolResultBlock.fromJson(json),
      'tool_search_tool_result' => ToolSearchToolResultBlock.fromJson(json),
      'container_upload' => ContainerUploadBlock.fromJson(json),
      'compaction' => CompactionBlock.fromJson(json),
      'mcp_tool_use' => MCPToolUseBlock.fromJson(json),
      'mcp_tool_listing' => McpToolListingBlock.fromJson(json),
      'mcp_tool_result' => MCPToolResultBlock.fromJson(json),
      'advisor_tool_result' => AdvisorToolResultBlock.fromJson(json),
      'fallback' => FallbackBlock.fromJson(json),
      _ => UnknownContentBlock.fromJson(json),
    };
  }

  /// Converts to JSON.
  Map<String, dynamic> toJson();
}

/// Text content block in a response.
@immutable
class TextBlock extends ContentBlock {
  /// The text content.
  final String text;

  /// Citations supporting this text block.
  final List<Citation>? citations;

  /// Creates a [TextBlock].
  const TextBlock({required this.text, this.citations});

  /// Creates a [TextBlock] from JSON.
  factory TextBlock.fromJson(Map<String, dynamic> json) {
    return TextBlock(
      text: json['text'] as String,
      citations: (json['citations'] as List?)
          ?.map((e) => Citation.fromJson(e as Map<String, dynamic>))
          .toList(),
    );
  }

  @override
  Map<String, dynamic> toJson() => {
    'type': 'text',
    'text': text,
    if (citations != null)
      'citations': citations!.map((e) => e.toJson()).toList(),
  };

  /// Creates a copy with replaced values.
  TextBlock copyWith({String? text, Object? citations = unsetCopyWithValue}) {
    return TextBlock(
      text: text ?? this.text,
      citations: citations == unsetCopyWithValue
          ? this.citations
          : citations as List<Citation>?,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TextBlock &&
          runtimeType == other.runtimeType &&
          text == other.text &&
          listsEqual(citations, other.citations);

  @override
  int get hashCode => Object.hash(text, listHash(citations));

  @override
  String toString() =>
      'TextBlock(text: [${text.length} chars], citations: $citations)';
}

/// Thinking (reasoning) content block in a response.
@immutable
class ThinkingBlock extends ContentBlock {
  /// The thinking/reasoning content.
  ///
  /// Empty when parsed from a partial streaming `content_block_start` (the
  /// text accumulates via `thinking_delta` events) or from an
  /// Anthropic-compatible server that omits it.
  final String thinking;

  /// Signature for the thinking block.
  ///
  /// Empty when parsed from a streaming `content_block_start`; the real value
  /// arrives later in a `signature_delta`. Also empty for Anthropic-compatible
  /// servers (e.g. MiniMax) that omit it.
  final String signature;

  /// Creates a [ThinkingBlock].
  const ThinkingBlock({required this.thinking, required this.signature});

  /// Creates a [ThinkingBlock] from JSON.
  ///
  /// `thinking` and `signature` are `required` only on the final response
  /// block per the API spec. A streaming `content_block_start` carries a
  /// *partial* thinking block whose `signature` (and initially `thinking`)
  /// are absent — the real values arrive later in `thinking_delta` /
  /// `signature_delta` events that the stream accumulator merges onto the
  /// message. Some Anthropic-compatible servers (e.g. MiniMax) likewise omit
  /// `signature` at block start. Defaulting to empty rather than throwing
  /// keeps parsing robust in all of these cases.
  factory ThinkingBlock.fromJson(Map<String, dynamic> json) {
    return ThinkingBlock(
      thinking: json['thinking'] as String? ?? '',
      signature: json['signature'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toJson() => {
    'type': 'thinking',
    'thinking': thinking,
    'signature': signature,
  };

  /// Creates a copy with replaced values.
  ThinkingBlock copyWith({String? thinking, String? signature}) {
    return ThinkingBlock(
      thinking: thinking ?? this.thinking,
      signature: signature ?? this.signature,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThinkingBlock &&
          runtimeType == other.runtimeType &&
          thinking == other.thinking &&
          signature == other.signature;

  @override
  int get hashCode => Object.hash(thinking, signature);

  @override
  String toString() =>
      'ThinkingBlock(thinking: [${thinking.length} chars], '
      'signature: [${signature.length} chars])';
}

/// Redacted thinking block (when thinking content is not available).
@immutable
class RedactedThinkingBlock extends ContentBlock {
  /// Opaque data for the redacted content.
  ///
  /// Empty when parsed from a partial streaming block or an
  /// Anthropic-compatible server that omits the field.
  final String data;

  /// Creates a [RedactedThinkingBlock].
  const RedactedThinkingBlock({required this.data});

  /// Creates a [RedactedThinkingBlock] from JSON.
  ///
  /// `data` defaults to empty string when absent or null, mirroring
  /// [ThinkingBlock.fromJson]: a streaming `content_block_start` (or an
  /// Anthropic-compatible server) may omit it rather than supplying the
  /// final value, so defaulting avoids crashing the parser.
  factory RedactedThinkingBlock.fromJson(Map<String, dynamic> json) {
    return RedactedThinkingBlock(data: json['data'] as String? ?? '');
  }

  @override
  Map<String, dynamic> toJson() => {'type': 'redacted_thinking', 'data': data};

  /// Creates a copy with replaced values.
  RedactedThinkingBlock copyWith({String? data}) {
    return RedactedThinkingBlock(data: data ?? this.data);
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RedactedThinkingBlock &&
          runtimeType == other.runtimeType &&
          data == other.data;

  @override
  int get hashCode => data.hashCode;

  @override
  String toString() => 'RedactedThinkingBlock(data: [${data.length} chars])';
}

/// Tool use block in a response.
@immutable
class ToolUseBlock extends ContentBlock {
  /// Unique identifier for this tool use.
  final String id;

  /// Name of the tool being used.
  final String name;

  /// Input parameters for the tool.
  final Map<String, dynamic> input;

  /// Caller metadata for this tool invocation.
  final ToolCaller? caller;

  /// For a toolset member tool use, the toolset family.
  final String? toolsetName;

  /// Typed browser or computer input once the tool use is complete.
  /// Returns null for a tool use that has no toolset family.
  ToolsetAction? get toolsetAction => switch (toolsetName) {
    final family? => ToolsetAction.decode(family, name, input),
    null => null,
  };

  /// Creates a [ToolUseBlock].
  const ToolUseBlock({
    required this.id,
    required this.name,
    required this.input,
    this.caller,
    this.toolsetName,
  });

  /// Creates a [ToolUseBlock] from JSON.
  factory ToolUseBlock.fromJson(Map<String, dynamic> json) {
    return ToolUseBlock(
      id: json['id'] as String,
      name: json['name'] as String,
      input: json['input'] as Map<String, dynamic>,
      caller: json['caller'] != null
          ? ToolCaller.fromJson(json['caller'] as Map<String, dynamic>)
          : null,
      toolsetName: json['toolset_name'] as String?,
    );
  }

  @override
  Map<String, dynamic> toJson() => {
    'type': 'tool_use',
    'id': id,
    'name': name,
    'input': input,
    if (caller != null) 'caller': caller!.toJson(),
    if (toolsetName != null) 'toolset_name': toolsetName,
  };

  /// Creates a copy with replaced values.
  ToolUseBlock copyWith({
    String? id,
    String? name,
    Map<String, dynamic>? input,
    Object? caller = unsetCopyWithValue,
    Object? toolsetName = unsetCopyWithValue,
  }) {
    return ToolUseBlock(
      id: id ?? this.id,
      name: name ?? this.name,
      input: input ?? this.input,
      caller: caller == unsetCopyWithValue
          ? this.caller
          : caller as ToolCaller?,
      toolsetName: toolsetName == unsetCopyWithValue
          ? this.toolsetName
          : toolsetName as String?,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ToolUseBlock &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          mapsEqual(input, other.input) &&
          caller == other.caller &&
          toolsetName == other.toolsetName;

  @override
  int get hashCode =>
      Object.hash(id, name, mapHash(input), caller, toolsetName);

  @override
  String toString() =>
      'ToolUseBlock(id: $id, name: $name, input: $input, caller: $caller, '
      'toolsetName: $toolsetName)';
}

