/// Compaction content block (beta).
///
/// Returned when server-side compaction is triggered. Can be round-tripped
/// back to subsequent requests to preserve compacted context.
@immutable
class CompactionBlock extends ContentBlock {
  /// Summary content for compacted context.
  ///
  /// When `null`, compaction failed and the block is a no-op if round-tripped.
  final String? content;

  /// Encrypted compaction payload for server-side context restoration.
  final String? encryptedContent;

  /// Signature over the summary. Pass it back unchanged on subsequent turns.
  final String? signature;

  /// Tool changes from the summarized range.
  ///
  /// Forward these provider objects unchanged, including nested definitions
  /// and an empty list when the server reports no tool changes.
  final List<Map<String, dynamic>>? toolChanges;

  /// Typed view of [toolChanges]. Replay still uses the original JSON.
  Iterable<CompactionToolChange>? get toolChangeBlocks =>
      toolChanges?.map(CompactionToolChange.fromJson);

  // These nullable beta fields must retain their wire presence during replay.
  final ({bool encryptedContent, bool signature, bool toolChanges}) _presence;

  /// Creates a [CompactionBlock].
  const CompactionBlock({
    required this.content,
    this.encryptedContent,
    this.signature,
    this.toolChanges,
  }) : _presence = (
         encryptedContent: true,
         signature: signature != null,
         toolChanges: toolChanges != null,
       );

  const CompactionBlock._({
    required this.content,
    required this.encryptedContent,
    required this.signature,
    required this.toolChanges,

    required this._presence,
  });

  /// Creates a [CompactionBlock] from JSON.
  factory CompactionBlock.fromJson(Map<String, dynamic> json) {
    final toolChanges = json['tool_changes'] as List<Object?>?;
    return CompactionBlock._(
      content: json['content'] as String?,
      encryptedContent: json['encrypted_content'] as String?,
      signature: json['signature'] as String?,
      presence: (
        encryptedContent: json.containsKey('encrypted_content'),
        signature: json.containsKey('signature'),
        toolChanges: json.containsKey('tool_changes'),
      ),
      toolChanges: toolChanges == null
          ? null
          : List.unmodifiable(
              toolChanges.map(
                (change) =>
                    deepUnmodifiableMap(change! as Map<String, dynamic>),
              ),
            ),
    );
  }

  @override
  Map<String, dynamic> toJson() => {
    'type': 'compaction',
    'content': content,
    if (_presence.encryptedContent) 'encrypted_content': encryptedContent,
    if (_presence.signature) 'signature': signature,
    if (_presence.toolChanges) 'tool_changes': toolChanges,
  };

  /// Creates a copy with replaced values.
  CompactionBlock copyWith({
    Object? content = unsetCopyWithValue,
    Object? encryptedContent = unsetCopyWithValue,
    Object? signature = unsetCopyWithValue,
    Object? toolChanges = unsetCopyWithValue,
  }) {
    return CompactionBlock._(
      content: content == unsetCopyWithValue
          ? this.content
          : content as String?,
      encryptedContent: encryptedContent == unsetCopyWithValue
          ? this.encryptedContent
          : encryptedContent as String?,
      presence: (
        encryptedContent:
            encryptedContent != unsetCopyWithValue ||
            _presence.encryptedContent,
        signature: signature == unsetCopyWithValue
            ? _presence.signature
            : signature != null,
        toolChanges: toolChanges == unsetCopyWithValue
            ? _presence.toolChanges
            : toolChanges != null,
      ),
      signature: signature == unsetCopyWithValue
          ? this.signature
          : signature as String?,
      toolChanges: toolChanges == unsetCopyWithValue
          ? this.toolChanges
          : toolChanges as List<Map<String, dynamic>>?,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CompactionBlock &&
          runtimeType == other.runtimeType &&
          content == other.content &&
          encryptedContent == other.encryptedContent &&
          signature == other.signature &&
          _presence == other._presence &&
          listOfMapsDeepEqual(toolChanges, other.toolChanges);

  @override
  int get hashCode => Object.hash(
    content,
    encryptedContent,
    signature,
    _presence,
    listOfMapsHashCode(toolChanges),
  );

  @override
  String toString() =>
      'CompactionBlock(content: $content, '
      'encryptedContent: ${encryptedContent == null ? 'null' : '[${encryptedContent!.length} chars]'}, '
      'signature: ${signature == null ? 'null' : '[${signature!.length} chars]'}, '
      'toolChanges: ${toolChanges?.length})';
}

/// Web search result content.
sealed class WebSearchResult {
  const WebSearchResult();

  /// Creates a [WebSearchResult] from JSON.
  ///
  /// The [json] parameter accepts either a `List` (array of search result
  /// items for the success case) or a `Map` (error object with
  /// `type: "web_search_tool_result_error"`).
  factory WebSearchResult.fromJson(Object json) {
    if (json is List) {
      return WebSearchResultSuccess.fromJson(json);
    }
    if (json is Map) {
      final map = json.cast<String, dynamic>();
      final type = map['type'];
      if (type is String) {
        if (type == 'web_search_tool_result_error') {
          return WebSearchResultError.fromJson(map);
        }
        throw FormatException('Unknown WebSearchResult type: $type');
      }
      throw const FormatException(
        'Invalid WebSearchResult: "type" must be a string',
      );
    }
    throw FormatException(
      'Expected List or Map for WebSearchResult, got ${json.runtimeType}',
    );
  }

  /// Converts to JSON.
  Object toJson();
}

