/// MCP tool use block in a response.
///
/// Represents a model-initiated tool call to an MCP server tool.
@immutable
class MCPToolUseBlock extends ContentBlock {
  /// Unique identifier for this tool use.
  final String id;

  /// Name of the MCP tool being used.
  final String name;

  /// Name of the MCP server providing the tool.
  final String serverName;

  /// Input parameters for the tool.
  final Map<String, dynamic> input;

  /// Creates an [MCPToolUseBlock].
  const MCPToolUseBlock({
    required this.id,
    required this.name,
    required this.serverName,
    required this.input,
  });

  /// Creates an [MCPToolUseBlock] from JSON.
  factory MCPToolUseBlock.fromJson(Map<String, dynamic> json) {
    return MCPToolUseBlock(
      id: json['id'] as String,
      name: json['name'] as String,
      serverName: json['server_name'] as String,
      input: json['input'] as Map<String, dynamic>,
    );
  }

  @override
  Map<String, dynamic> toJson() => {
    'type': 'mcp_tool_use',
    'id': id,
    'name': name,
    'server_name': serverName,
    'input': input,
  };

  /// Creates a copy with replaced values.
  MCPToolUseBlock copyWith({
    String? id,
    String? name,
    String? serverName,
    Map<String, dynamic>? input,
  }) {
    return MCPToolUseBlock(
      id: id ?? this.id,
      name: name ?? this.name,
      serverName: serverName ?? this.serverName,
      input: input ?? this.input,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MCPToolUseBlock &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          serverName == other.serverName &&
          mapsEqual(input, other.input);

  @override
  int get hashCode => Object.hash(id, name, serverName, mapHash(input));

  @override
  String toString() =>
      'MCPToolUseBlock(id: $id, name: $name, '
      'serverName: $serverName, input: $input)';
}

/// The MCP tool list captured for a named server in a conversation.
@immutable
final class McpToolListingBlock extends ContentBlock {
  /// Creates a tool listing block.
  McpToolListingBlock({
    required this.serverName,
    required List<McpListedTool> tools,
  }) : tools = List.unmodifiable(tools);

  /// Parses the current `mcp_tool_listing` payload.
  factory McpToolListingBlock.fromJson(Map<String, dynamic> json) {
    if (json case {
      'type': 'mcp_tool_listing',
      'mcp_server_name': final String serverName,
      'tools': final List<Object?> tools,
    }) {
      return McpToolListingBlock(
        serverName: serverName,
        tools: tools
            .map(
              (tool) => McpListedTool.fromJson(tool! as Map<String, dynamic>),
            )
            .toList(),
      );
    }
    throw const FormatException('Invalid MCP tool listing block');
  }

  /// Name of the MCP server in the Messages request.
  final String serverName;

  /// Tools Claude saw, in the order reported by the server.
  final List<McpListedTool> tools;

  @override
  Map<String, dynamic> toJson() => {
    'type': 'mcp_tool_listing',
    'mcp_server_name': serverName,
    'tools': tools.map((tool) => tool.toJson()).toList(),
  };

  /// Copies the block with selected properties replaced.
  McpToolListingBlock copyWith({
    String? serverName,
    List<McpListedTool>? tools,
  }) => McpToolListingBlock(
    serverName: serverName ?? this.serverName,
    tools: tools ?? this.tools,
  );

  @override
  bool operator ==(Object other) =>
      other is McpToolListingBlock &&
      serverName == other.serverName &&
      listsEqual(tools, other.tools);

  @override
  int get hashCode => Object.hash(serverName, listHash(tools));

  @override
  String toString() =>
      'McpToolListingBlock(serverName: $serverName, tools: ${tools.length})';
}

/// Content of an MCP tool result — either a plain string or a list of
/// text blocks.
sealed class MCPToolResultContent {
  const MCPToolResultContent();

  /// Creates from a plain string.
  factory MCPToolResultContent.text(String text) = MCPToolResultStringContent;

  /// Creates from a list of text blocks.
  factory MCPToolResultContent.blocks(List<TextBlock> blocks) =
      MCPToolResultBlocksContent;

  /// Creates an [MCPToolResultContent] from JSON.
  factory MCPToolResultContent.fromJson(Object json) {
    if (json is String) return MCPToolResultStringContent(json);
    if (json is List) {
      return MCPToolResultBlocksContent(
        json.map((e) => TextBlock.fromJson(e as Map<String, dynamic>)).toList(),
      );
    }
    throw FormatException(
      'Expected String or List for MCPToolResultContent, '
      'got ${json.runtimeType}',
    );
  }

  /// Converts to JSON.
  Object toJson();
}

