/// Error codes for advisor tool result errors.
enum AdvisorToolResultErrorCode {
  /// The advisor sub-inference timed out.
  executionTimeExceeded,

  /// The request reached the max_uses cap.
  maxUsesExceeded,

  /// The requested advisor model could not be found.
  modelNotFound,

  /// The advisor sub-inference hit capacity limits.
  overloaded,

  /// The transcript exceeded the advisor model's context window.
  promptTooLong,

  /// The advisor sub-inference was rate-limited.
  tooManyRequests,

  /// Any other advisor failure.
  unavailable,

  /// Forward-compatible fallback for unrecognized error codes.
  unknown;

  /// Creates an [AdvisorToolResultErrorCode] from JSON.
  factory AdvisorToolResultErrorCode.fromJson(String value) => switch (value) {
    'execution_time_exceeded' => executionTimeExceeded,
    'max_uses_exceeded' => maxUsesExceeded,
    'model_not_found' => modelNotFound,
    'overloaded' => overloaded,
    'prompt_too_long' => promptTooLong,
    'too_many_requests' => tooManyRequests,
    'unavailable' => unavailable,
    _ => unknown,
  };

  /// Converts to a known JSON string.
  ///
  /// Returns `'unknown'` for [unknown] — this is lossy for unrecognized codes.
  /// For round-trip serialization, use [AdvisorToolResultError.rawErrorCode]
  /// instead of `errorCode.toJson()`.
  String toJson() => switch (this) {
    executionTimeExceeded => 'execution_time_exceeded',
    maxUsesExceeded => 'max_uses_exceeded',
    modelNotFound => 'model_not_found',
    overloaded => 'overloaded',
    promptTooLong => 'prompt_too_long',
    tooManyRequests => 'too_many_requests',
    unavailable => 'unavailable',
    unknown => 'unknown',
  };
}

/// Error codes for web search tool result errors.
enum WebSearchToolResultErrorCode {
  /// The tool input failed validation.
  invalidToolInput,

  /// The web search service was unavailable.
  unavailable,

  /// The request reached the max_uses cap.
  maxUsesExceeded,

  /// The request was rate-limited.
  tooManyRequests,

  /// The search query exceeded the maximum length.
  queryTooLong,

  /// The request payload was too large.
  requestTooLarge,

  /// Forward-compatible fallback for unrecognized error codes.
  unknown;

  /// Creates a [WebSearchToolResultErrorCode] from JSON.
  factory WebSearchToolResultErrorCode.fromJson(String value) =>
      switch (value) {
        'invalid_tool_input' => invalidToolInput,
        'unavailable' => unavailable,
        'max_uses_exceeded' => maxUsesExceeded,
        'too_many_requests' => tooManyRequests,
        'query_too_long' => queryTooLong,
        'request_too_large' => requestTooLarge,
        _ => unknown,
      };

  /// Converts to a known JSON string.
  ///
  /// Returns `'unknown'` for [unknown] — this is lossy for unrecognized codes.
  /// For round-trip serialization, use [WebSearchResultError.rawErrorCode]
  /// instead of `errorCode.toJson()`.
  String toJson() => switch (this) {
    invalidToolInput => 'invalid_tool_input',
    unavailable => 'unavailable',
    maxUsesExceeded => 'max_uses_exceeded',
    tooManyRequests => 'too_many_requests',
    queryTooLong => 'query_too_long',
    requestTooLarge => 'request_too_large',
    unknown => 'unknown',
  };
}
